inline bool boundary(const study_gl::GlApi& gl, Mode mode) noexcept {
    if (mode != Mode::submit && mode != Mode::flush && mode != Mode::finish) return false;
    if (gl.GetError()) return false;
    switch (mode) {
    case Mode::submit: break;
    case Mode::flush: gl.Flush(); break;
    case Mode::finish: gl.Finish(); break;
    }
    return gl.GetError() == 0;
}

SwapIntervalReport platform_set_swap_interval(int requested)
{
    if ((requested != 0 && requested != 1) || !active || active->should_close ||
        SDL_GL_GetCurrentContext() != active->context.get() ||
        SDL_GL_GetCurrentWindow() != active->window.get()) return {};
    SwapIntervalReport report;
    report.attempted = true;
    report.accepted = SDL_GL_SetSwapInterval(requested) == 0;
    report.reported_interval = SDL_GL_GetSwapInterval();
    return report;
}

bool platform_present()
{
    if (!active || SDL_GL_GetCurrentContext() != active->context.get() ||
        SDL_GL_GetCurrentWindow() != active->window.get()) return false;
    const auto size = platform_drawable_size();
    if (size.width <= 0 || size.height <= 0) return false;
    SDL_GL_SwapWindow(active->window.get());
    return true;
}

inline std::optional<CpuStages> summarize(std::uint64_t begin,
                                          std::uint64_t after_submit,
                                          std::uint64_t after_sync,
                                          std::uint64_t after_present,
                                          std::uint64_t frequency) noexcept {
    if (frequency == 0) {
        return std::nullopt;
    }

    // Reject any decreasing timestamp before doing arithmetic, so every delta
    // computed below is guaranteed to be non-negative.
    if (after_submit < begin || after_sync < after_submit || after_present < after_sync) {
        return std::nullopt;
    }

    // Integer subtraction first (exact even near UINT64_MAX), then to double, then to ms.
    CpuStages stages{};
    stages.submit_ms = ticks_to_ms(after_submit - begin, frequency);
    stages.sync_ms = ticks_to_ms(after_sync - after_submit, frequency);
    stages.present_ms = ticks_to_ms(after_present - after_sync, frequency);
    return stages;
}

using Clock = std::chrono::steady_clock;
const auto origin = Clock::now();
const auto ticks = [&origin]() -> std::uint64_t {
    return static_cast<std::uint64_t>(std::chrono::duration_cast<std::chrono::nanoseconds>(
        Clock::now() - origin).count());
};
if (!study_blend_scene::render(gl, program.name(), vertex_array.name(),
                              vertex_buffer.vertex_count(), experiment, size.width, size.height)) return 1;
const auto after_submit = ticks();
if (!study_submission::boundary(gl, mode)) return 1;
const auto after_sync = ticks();
if (platform_present()) {
    const auto after_present = ticks();
    const auto sample = study_timing::summarize(0, after_submit, after_sync,
                                               after_present, 1000000000);
    if (!sample) return 1;
    samples.push_back(*sample);
